<?php
namespace App\Http\Controllers;
use App\Models\Supplier; use App\Services\Permissions\ProfilePermissionService; use App\Services\SupplierNormalizer; use App\Services\SupplierSearchService; use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class SupplierController extends Controller { private function auth(Request $r){abort_unless(app(ProfilePermissionService::class)->allows($r->user(),'admin.access.manage',['module'=>'fleet','division_id'=>session('active_division_id'),'location_id'=>session('active_location_id')]),403);} public function index(Request $r,SupplierSearchService $search){$this->auth($r);$tenant=$r->user()->tenant_id;$items=Supplier::forTenant($tenant)->with('aliases')->when($r->q,fn($q)=>$q->where('normalized_name','like','%'.app(SupplierNormalizer::class)->normalizeName($r->q).'%'))->orderBy('trade_name')->paginate(20);return view('suppliers.index',compact('items'));} public function search(Request $r,SupplierSearchService $search){$this->auth($r);return response()->json($search->search($r->user()->tenant_id,(string)$r->q));} public function store(Request $r,SupplierNormalizer $n){$this->auth($r);$d=$this->data($r,$n);$d['tenant_id']=$r->user()->tenant_id;$s=Supplier::create($d);$this->aliases($s,$r,$n);return redirect()->route('suppliers.index')->with('success','Fornecedor cadastrado.');} public function update(Request $r,Supplier $supplier,SupplierNormalizer $n){$this->auth($r);abort_unless($supplier->tenant_id===$r->user()->tenant_id,404);$supplier->update($this->data($r,$n,$supplier));$this->aliases($supplier,$r,$n);return back()->with('success','Fornecedor atualizado.');} private function data(Request $r,SupplierNormalizer $n,?Supplier $s=null):array{$d=$r->validate(['trade_name'=>['nullable','string','max:255','required_without:legal_name'],'legal_name'=>['nullable','string','max:255'],'document'=>['nullable','string','max:20'],'active'=>['nullable','boolean'],'aliases'=>['nullable','array'],'aliases.*'=>['string','max:255']]);$doc=$n->normalizeDocument($d['document']??null);if($doc&&!$n->validDocument($doc))return abort(422,'CPF/CNPJ inválido.');if($doc&&Supplier::forTenant($r->user()->tenant_id)->where('document',$doc)->when($s,fn($q)=>$q->whereKeyNot($s->id))->exists())abort(422,'Este CPF/CNPJ já está cadastrado neste tenant.');$d['document']=$doc;$d['document_type']=$n->detectDocumentType($doc);$d['normalized_name']=$n->normalizeName($d['trade_name']?:$d['legal_name']);$d['active']=$r->boolean('active',true);unset($d['aliases']);return $d;} private function aliases(Supplier $s,Request $r,SupplierNormalizer $n):void{foreach($r->input('aliases',[]) as $a){$a=trim($a);if($a!=='')$s->aliases()->firstOrCreate(['normalized_alias'=>$n->normalizeName($a)],['alias'=>$a]);}} }
